-- =============================================================================
-- Space Booking API: database schema (PostgreSQL 17)
-- =============================================================================
-- Generated by hand from docs/erd.md (18 tables). docs/erd.md stays the source
-- of truth; update both together.
--
-- Purpose: reference DDL for review, ERD tools (dbdiagram, DBeaver, pgAdmin)
-- and as the basis for the first TypeORM migration. The app itself only changes
-- the schema through migrations (AGENTS.md section 7); do not apply this file to
-- a database managed by migrations.
--
-- Try it on an empty local database:
--   psql -h localhost -U <user> -d <empty_db> -v ON_ERROR_STOP=1 -f docs/schema/db.sql
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- Extensions
-- -----------------------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS btree_gist;  -- uuid "=" inside the GiST exclusion constraint
CREATE EXTENSION IF NOT EXISTS citext;      -- case-insensitive email
CREATE EXTENSION IF NOT EXISTS pgcrypto;    -- gen_random_uuid()

-- -----------------------------------------------------------------------------
-- Enums (docs/erd.md section 4)
-- -----------------------------------------------------------------------------
CREATE TYPE user_role            AS ENUM ('ADMIN', 'USER');
CREATE TYPE auth_provider        AS ENUM ('GOOGLE', 'FACEBOOK');
CREATE TYPE otp_purpose          AS ENUM ('EMAIL_VERIFY', 'PASSWORD_RESET', 'TELEGRAM_LINK');
CREATE TYPE place_type           AS ENUM ('LIBRARY', 'CAFE', 'COWORKING', 'OTHER');
CREATE TYPE seat_status          AS ENUM ('ACTIVE', 'MAINTENANCE', 'UNAVAILABLE');
CREATE TYPE booking_source       AS ENUM ('APP', 'API_CLIENT', 'ADMIN');
CREATE TYPE booking_status       AS ENUM ('PENDING', 'CHECKED_IN', 'CHECKOUT_OVERDUE',
                                          'COMPLETED', 'CANCELLED', 'EXPIRED');
CREATE TYPE attendance_method    AS ENUM ('QR', 'MANUAL');
CREATE TYPE booking_event_type   AS ENUM ('CREATED', 'MODIFIED', 'EXTENDED', 'CHECKED_IN',
                                          'CHECKED_OUT', 'CANCELLED', 'EXPIRED', 'OVERDUE',
                                          'OVERDUE_RESOLVED');
CREATE TYPE qr_purpose           AS ENUM ('CHECK_IN', 'CHECK_OUT');
CREATE TYPE notification_channel AS ENUM ('EMAIL', 'TELEGRAM');
CREATE TYPE notification_type    AS ENUM ('EMAIL_VERIFY_OTP', 'PASSWORD_RESET_OTP',
                                          'BOOKING_CONFIRMED', 'BOOKING_CANCELLED',
                                          'LATE_CHECKIN', 'CHECKOUT_REMINDER',
                                          'BOOKING_EXPIRED', 'FORGOTTEN_CHECKOUT');
CREATE TYPE notification_status  AS ENUM ('PENDING', 'SENT', 'FAILED', 'SKIPPED');

-- -----------------------------------------------------------------------------
-- updated_at helper
-- TypeORM's @UpdateDateColumn sets updated_at on ORM saves; this trigger keeps
-- it correct for raw SQL / query-builder updates too.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

-- =============================================================================
-- Auth & users
-- =============================================================================

CREATE TABLE users (
  id                 uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  role               user_role    NOT NULL DEFAULT 'USER',
  name               varchar(100) NOT NULL,
  email              citext       NOT NULL,
  password_hash      varchar(255),                       -- NULL = social sign-in only
  avatar_url         varchar(500),
  email_verified_at  timestamptz,
  is_active          boolean      NOT NULL DEFAULT true,
  no_show_count      integer      NOT NULL DEFAULT 0,
  created_at         timestamptz  NOT NULL DEFAULT now(),
  updated_at         timestamptz  NOT NULL DEFAULT now(),
  deleted_at         timestamptz,
  CONSTRAINT users_email_uk          UNIQUE (email),
  CONSTRAINT users_no_show_count_chk CHECK (no_show_count >= 0)
);
-- "At least one sign-in method" (password or auth_identities row) is cross-table:
-- enforced in the auth service, not here.

CREATE TABLE auth_identities (
  id                uuid          PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id           uuid          NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  provider          auth_provider NOT NULL,
  provider_user_id  varchar(255)  NOT NULL,              -- Google "sub" / Facebook user id
  provider_email    citext,
  email_verified    boolean       NOT NULL DEFAULT false,
  display_name      varchar(100),
  avatar_url        varchar(500),
  linked_at         timestamptz   NOT NULL DEFAULT now(),
  last_login_at     timestamptz,
  CONSTRAINT auth_identities_provider_account_uk UNIQUE (provider, provider_user_id),
  CONSTRAINT auth_identities_user_provider_uk    UNIQUE (user_id, provider)
);

CREATE TABLE user_otps (
  id            uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  purpose       otp_purpose  NOT NULL,
  code_hash     varchar(255) NOT NULL,                   -- hash only, never the code
  expires_at    timestamptz  NOT NULL,
  used_at       timestamptz,
  attempts      smallint     NOT NULL DEFAULT 0,
  last_sent_at  timestamptz  NOT NULL DEFAULT now(),
  created_at    timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT user_otps_attempts_chk CHECK (attempts >= 0)
);
-- At most one live code per user and purpose.
CREATE UNIQUE INDEX user_otps_live_uk ON user_otps (user_id, purpose) WHERE used_at IS NULL;

CREATE TABLE refresh_tokens (
  id              uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  token_hash      varchar(255) NOT NULL,
  expires_at      timestamptz  NOT NULL,
  revoked_at      timestamptz,
  replaced_by_id  uuid         REFERENCES refresh_tokens (id) ON DELETE SET NULL,
  user_agent      varchar(255),
  ip              inet,
  created_at      timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT refresh_tokens_token_hash_uk UNIQUE (token_hash)
);

-- =============================================================================
-- Places & seats
-- =============================================================================

CREATE TABLE places (
  id           uuid             PRIMARY KEY DEFAULT gen_random_uuid(),
  name         varchar(150)     NOT NULL,
  type         place_type       NOT NULL,
  description  text,
  address      varchar(255)     NOT NULL,
  lat          double precision,
  lng          double precision,
  timezone     varchar(64)      NOT NULL DEFAULT 'Asia/Phnom_Penh',  -- IANA, validated in the app
  is_active    boolean          NOT NULL DEFAULT true,
  created_at   timestamptz      NOT NULL DEFAULT now(),
  updated_at   timestamptz      NOT NULL DEFAULT now(),
  deleted_at   timestamptz,
  CONSTRAINT places_lat_chk CHECK (lat BETWEEN -90 AND 90),
  CONSTRAINT places_lng_chk CHECK (lng BETWEEN -180 AND 180)
);

CREATE TABLE place_opening_hours (
  id               uuid     PRIMARY KEY DEFAULT gen_random_uuid(),
  place_id         uuid     NOT NULL REFERENCES places (id) ON DELETE CASCADE,
  weekday          smallint NOT NULL,                    -- 0 = Sunday .. 6 = Saturday
  open_time        time     NOT NULL,
  close_time       time     NOT NULL,
  closes_next_day  boolean  NOT NULL DEFAULT false,      -- overnight venues
  CONSTRAINT place_opening_hours_place_weekday_uk UNIQUE (place_id, weekday),
  CONSTRAINT place_opening_hours_weekday_chk      CHECK (weekday BETWEEN 0 AND 6),
  CONSTRAINT place_opening_hours_times_chk        CHECK (closes_next_day OR open_time < close_time)
);

CREATE TABLE place_closures (
  id        uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  place_id  uuid         NOT NULL REFERENCES places (id) ON DELETE CASCADE,
  date      date         NOT NULL,                       -- local date in places.timezone
  reason    varchar(255),
  CONSTRAINT place_closures_place_date_uk UNIQUE (place_id, date)
);

CREATE TABLE booking_policies (
  place_id                   uuid        PRIMARY KEY REFERENCES places (id) ON DELETE CASCADE,
  checkin_grace_minutes      smallint    NOT NULL DEFAULT 15,
  checkout_reminder_minutes  smallint    NOT NULL DEFAULT 15,
  overdue_alert_minutes      smallint    NOT NULL DEFAULT 15,
  min_minutes                smallint    NOT NULL DEFAULT 30,
  max_minutes                smallint    NOT NULL DEFAULT 240,
  slot_minutes               smallint    NOT NULL DEFAULT 15,
  max_advance_days           smallint    NOT NULL DEFAULT 7,
  max_active_per_user        smallint    NOT NULL DEFAULT 1,
  max_extensions             smallint    NOT NULL DEFAULT 2,
  modify_cutoff_minutes      smallint    NOT NULL DEFAULT 30,
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT booking_policies_grace_chk          CHECK (checkin_grace_minutes >= 0),
  CONSTRAINT booking_policies_reminder_chk       CHECK (checkout_reminder_minutes >= 0),
  CONSTRAINT booking_policies_overdue_chk        CHECK (overdue_alert_minutes >= 0),
  CONSTRAINT booking_policies_min_chk            CHECK (min_minutes >= 1),
  CONSTRAINT booking_policies_max_chk            CHECK (max_minutes >= min_minutes),
  CONSTRAINT booking_policies_slot_chk           CHECK (slot_minutes >= 1),
  CONSTRAINT booking_policies_advance_chk        CHECK (max_advance_days >= 0),
  CONSTRAINT booking_policies_active_chk         CHECK (max_active_per_user >= 1),
  CONSTRAINT booking_policies_extensions_chk     CHECK (max_extensions >= 0),
  CONSTRAINT booking_policies_modify_cutoff_chk  CHECK (modify_cutoff_minutes >= 0)
);

CREATE TABLE areas (
  id           uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  place_id     uuid         NOT NULL REFERENCES places (id) ON DELETE RESTRICT,
  name         varchar(100) NOT NULL,
  floor        varchar(30),
  description  text,
  is_active    boolean      NOT NULL DEFAULT true,
  created_at   timestamptz  NOT NULL DEFAULT now(),
  updated_at   timestamptz  NOT NULL DEFAULT now(),
  deleted_at   timestamptz,
  -- Target of the composite FK from seats (keeps a seat's area in the same place).
  CONSTRAINT areas_id_place_uk UNIQUE (id, place_id)
);
CREATE UNIQUE INDEX areas_place_name_uk ON areas (place_id, name) WHERE deleted_at IS NULL;

CREATE TABLE seats (
  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  place_id    uuid        NOT NULL REFERENCES places (id) ON DELETE RESTRICT,
  area_id     uuid,                                      -- NULL = no area
  label       varchar(30) NOT NULL,
  features    jsonb       NOT NULL DEFAULT '{}'::jsonb,  -- power, window, desk size
  status      seat_status NOT NULL DEFAULT 'ACTIVE',
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  deleted_at  timestamptz,
  -- MATCH SIMPLE (default): no check when area_id is NULL.
  CONSTRAINT seats_area_same_place_fk FOREIGN KEY (area_id, place_id)
    REFERENCES areas (id, place_id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX seats_place_label_uk ON seats (place_id, label) WHERE deleted_at IS NULL;

-- =============================================================================
-- Integration: API clients (created before bookings, which reference it)
-- =============================================================================

CREATE TABLE api_clients (
  id            uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  name          varchar(100) NOT NULL,
  key_prefix    varchar(12)  NOT NULL,
  api_key_hash  varchar(255) NOT NULL,                   -- raw key shown once at creation
  scopes        text[]       NOT NULL DEFAULT '{}',      -- e.g. places:read, bookings:write
  is_active     boolean      NOT NULL DEFAULT true,
  last_used_at  timestamptz,
  created_at    timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT api_clients_name_uk         UNIQUE (name),
  CONSTRAINT api_clients_api_key_hash_uk UNIQUE (api_key_hash)
);

-- =============================================================================
-- Bookings
-- =============================================================================

CREATE TABLE bookings (
  id                uuid              PRIMARY KEY DEFAULT gen_random_uuid(),
  seat_id           uuid              NOT NULL REFERENCES seats (id)       ON DELETE RESTRICT,
  user_id           uuid              NOT NULL REFERENCES users (id)       ON DELETE RESTRICT,
  client_id         uuid              REFERENCES api_clients (id)          ON DELETE RESTRICT,
  source            booking_source    NOT NULL DEFAULT 'APP',
  time_range        tstzrange         NOT NULL,          -- [start, end)
  status            booking_status    NOT NULL DEFAULT 'PENDING',
  checked_in_at     timestamptz,
  checked_in_by     uuid              REFERENCES users (id) ON DELETE RESTRICT,
  check_in_method   attendance_method,
  checked_out_at    timestamptz,
  checked_out_by    uuid              REFERENCES users (id) ON DELETE RESTRICT,
  check_out_method  attendance_method,
  cancelled_at      timestamptz,
  cancelled_by      uuid              REFERENCES users (id) ON DELETE RESTRICT,
  cancel_reason     varchar(255),
  expired_at        timestamptz,
  extension_count   smallint          NOT NULL DEFAULT 0,
  idempotency_key   varchar(100),
  version           integer           NOT NULL DEFAULT 1,  -- optimistic lock (@VersionColumn)
  created_at        timestamptz       NOT NULL DEFAULT now(),
  updated_at        timestamptz       NOT NULL DEFAULT now(),

  -- Core guarantee: no double-booking (also guards modify / extend UPDATEs).
  -- Violation = SQLSTATE 23P01, mapped to 409 Conflict by the bookings service.
  CONSTRAINT no_double_booking
    EXCLUDE USING gist (seat_id WITH =, time_range WITH &&)
    WHERE (status IN ('PENDING', 'CHECKED_IN', 'CHECKOUT_OVERDUE')),

  -- Half-open, bounded, non-empty ranges.
  CONSTRAINT bookings_range_valid CHECK (
    NOT isempty(time_range)
    AND lower_inc(time_range) AND NOT upper_inc(time_range)
    AND NOT lower_inf(time_range) AND NOT upper_inf(time_range)
  ),

  -- Timestamps must match status.
  CONSTRAINT bookings_cancel_consistent   CHECK ((status = 'CANCELLED') = (cancelled_at IS NOT NULL)),
  CONSTRAINT bookings_expire_consistent   CHECK ((status = 'EXPIRED')   = (expired_at IS NOT NULL)),
  CONSTRAINT bookings_checkin_consistent  CHECK (
    (status IN ('CHECKED_IN', 'CHECKOUT_OVERDUE', 'COMPLETED')) = (checked_in_at IS NOT NULL)
  ),
  CONSTRAINT bookings_checkout_consistent CHECK (
    ((status = 'COMPLETED') = (checked_out_at IS NOT NULL))
    AND (checked_out_at IS NULL OR checked_out_at >= checked_in_at)
  ),
  CONSTRAINT bookings_checkin_method_chk  CHECK ((checked_in_at IS NULL)  = (check_in_method IS NULL)),
  CONSTRAINT bookings_checkout_method_chk CHECK ((checked_out_at IS NULL) = (check_out_method IS NULL)),

  -- client_id is set exactly when the booking came from an API client.
  CONSTRAINT bookings_client_consistent   CHECK ((source = 'API_CLIENT') = (client_id IS NOT NULL)),
  CONSTRAINT bookings_extension_count_chk CHECK (extension_count >= 0)
);
-- A retried POST /bookings with the same Idempotency-Key returns the original booking.
CREATE UNIQUE INDEX bookings_user_idempotency_uk
  ON bookings (user_id, idempotency_key) WHERE idempotency_key IS NOT NULL;

CREATE TABLE booking_events (
  id               uuid               PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id       uuid               NOT NULL REFERENCES bookings (id)    ON DELETE CASCADE,
  type             booking_event_type NOT NULL,
  old_range        tstzrange,                            -- MODIFIED / EXTENDED
  new_range        tstzrange,
  actor_user_id    uuid               REFERENCES users (id)       ON DELETE SET NULL,
  actor_client_id  uuid               REFERENCES api_clients (id) ON DELETE SET NULL,
  actor_system     boolean            NOT NULL DEFAULT false,    -- scheduled jobs
  metadata         jsonb              NOT NULL DEFAULT '{}'::jsonb,
  created_at       timestamptz        NOT NULL DEFAULT now(),
  CONSTRAINT booking_events_actor_chk
    CHECK (actor_system OR actor_user_id IS NOT NULL OR actor_client_id IS NOT NULL)
);

CREATE TABLE booking_qr_tokens (
  id          uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id  uuid         NOT NULL REFERENCES bookings (id) ON DELETE CASCADE,
  purpose     qr_purpose   NOT NULL,
  token_hash  varchar(255) NOT NULL,                     -- hash only; QR encodes the raw token
  expires_at  timestamptz  NOT NULL,
  used_at     timestamptz,
  revoked_at  timestamptz,
  created_at  timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT booking_qr_tokens_token_hash_uk UNIQUE (token_hash)
);
-- At most one live QR per booking and action.
CREATE UNIQUE INDEX booking_qr_tokens_live_uk
  ON booking_qr_tokens (booking_id, purpose) WHERE used_at IS NULL AND revoked_at IS NULL;

-- =============================================================================
-- Notifications
-- =============================================================================

CREATE TABLE telegram_accounts (
  id           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  chat_id      bigint      NOT NULL,
  username     varchar(64),
  linked_at    timestamptz NOT NULL DEFAULT now(),
  unlinked_at  timestamptz
);
-- One live link per user and per chat; old links kept for history.
CREATE UNIQUE INDEX telegram_accounts_user_live_uk ON telegram_accounts (user_id) WHERE unlinked_at IS NULL;
CREATE UNIQUE INDEX telegram_accounts_chat_live_uk ON telegram_accounts (chat_id) WHERE unlinked_at IS NULL;

CREATE TABLE notifications (
  id            uuid                 PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       uuid                 NOT NULL REFERENCES users (id)    ON DELETE CASCADE,
  booking_id    uuid                 REFERENCES bookings (id)          ON DELETE CASCADE,  -- NULL for auth emails
  channel       notification_channel NOT NULL,
  type          notification_type    NOT NULL,
  status        notification_status  NOT NULL DEFAULT 'PENDING',
  scheduled_at  timestamptz          NOT NULL DEFAULT now(),
  sent_at       timestamptz,
  attempts      smallint             NOT NULL DEFAULT 0,
  last_error    text,
  payload       jsonb                NOT NULL DEFAULT '{}'::jsonb,  -- never OTP codes or tokens
  created_at    timestamptz          NOT NULL DEFAULT now(),
  -- EMAIL is for auth OTPs only; booking alerts go to TELEGRAM.
  CONSTRAINT notifications_channel_type_chk CHECK (
    (channel = 'EMAIL') = (type IN ('EMAIL_VERIFY_OTP', 'PASSWORD_RESET_OTP'))
  ),
  CONSTRAINT notifications_sent_consistent CHECK ((status = 'SENT') = (sent_at IS NOT NULL)),
  CONSTRAINT notifications_attempts_chk    CHECK (attempts >= 0)
);
-- Jobs can run repeatedly without double-sending.
CREATE UNIQUE INDEX notifications_booking_type_channel_uk
  ON notifications (booking_id, type, channel) WHERE booking_id IS NOT NULL;

-- =============================================================================
-- Integration: outbox (we publish) and inbox (we consume)
-- No FKs on purpose: these are message logs, decoupled from the rows they describe.
-- =============================================================================

CREATE TABLE outbox_events (
  id              uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  aggregate_type  varchar(50)  NOT NULL,                 -- booking, seat, place, user
  aggregate_id    uuid         NOT NULL,
  event_type      varchar(100) NOT NULL,                 -- RabbitMQ routing key
  payload         jsonb        NOT NULL,                 -- no secrets / token fields
  occurred_at     timestamptz  NOT NULL DEFAULT now(),
  published_at    timestamptz,
  attempts        smallint     NOT NULL DEFAULT 0,
  last_error      text,
  CONSTRAINT outbox_events_attempts_chk CHECK (attempts >= 0)
);

CREATE TABLE inbox_events (
  id            uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  source        varchar(100) NOT NULL,                   -- 'telegram' or the producing service
  message_id    varchar(100) NOT NULL,                   -- RabbitMQ message_id / Telegram update_id
  event_type    varchar(100) NOT NULL,
  payload       jsonb        NOT NULL,
  received_at   timestamptz  NOT NULL DEFAULT now(),
  processed_at  timestamptz,
  error         text,
  CONSTRAINT inbox_events_source_message_uk UNIQUE (source, message_id)
);

-- =============================================================================
-- Indexes (docs/erd.md section 6)
-- The GiST index on bookings (seat_id, time_range) is created by no_double_booking.
-- UNIQUE constraints above already create their own indexes.
-- =============================================================================

CREATE INDEX bookings_user_created_idx        ON bookings (user_id, created_at DESC);
-- Jobs: expire (PENDING by start) and overdue / reminders (CHECKED_IN by end).
CREATE INDEX bookings_status_start_idx        ON bookings (status, lower(time_range));
CREATE INDEX bookings_status_end_idx          ON bookings (status, upper(time_range));
CREATE INDEX bookings_client_idx              ON bookings (client_id) WHERE client_id IS NOT NULL;
CREATE INDEX booking_events_booking_idx       ON booking_events (booking_id, created_at);
CREATE INDEX booking_qr_tokens_booking_idx    ON booking_qr_tokens (booking_id);
CREATE INDEX seats_place_area_idx             ON seats (place_id, area_id);
CREATE INDEX seats_features_gin_idx           ON seats USING gin (features);
CREATE INDEX areas_place_idx                  ON areas (place_id);
CREATE INDEX auth_identities_user_idx         ON auth_identities (user_id);
CREATE INDEX user_otps_user_purpose_idx       ON user_otps (user_id, purpose);
CREATE INDEX refresh_tokens_user_idx          ON refresh_tokens (user_id);
CREATE INDEX notifications_pending_due_idx    ON notifications (scheduled_at) WHERE status = 'PENDING';
CREATE INDEX notifications_user_created_idx   ON notifications (user_id, created_at DESC);
CREATE INDEX outbox_events_unpublished_idx    ON outbox_events (occurred_at) WHERE published_at IS NULL;

-- =============================================================================
-- updated_at triggers
-- =============================================================================

CREATE TRIGGER users_set_updated_at            BEFORE UPDATE ON users            FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER places_set_updated_at           BEFORE UPDATE ON places           FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER booking_policies_set_updated_at BEFORE UPDATE ON booking_policies FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER areas_set_updated_at            BEFORE UPDATE ON areas            FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER seats_set_updated_at            BEFORE UPDATE ON seats            FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER bookings_set_updated_at         BEFORE UPDATE ON bookings         FOR EACH ROW EXECUTE FUNCTION set_updated_at();

COMMIT;
